window.VZOROVA_ZKOUSKA = {"sada":"cvicna-1","oficialni":false,"otazky":[{"id":"UP-1-01","n":1,"lo":"FL-1.1.1","k":"K1","k3":true,"vyber":1,"q":"Testovací případy jsou navrhovány v rané fázi životního cyklu a testovací báze je přitom prověřována prostřednictvím návrhu testů. Kterého typického cíle testování se tím NEJLÉPE dosahuje?","m":["Ohodnocení pracovních produktů, jako jsou požadavky a návrhy","Ověření souladu testovaného objektu s právními předpisy","Vytvoření důvěry v úroveň kvality testovaného objektu","Poskytnutí informací zainteresovaným stranám pro rozhodnutí"],"ok":[0],"vys":{"a":"Je správně. Návrh testů v rané fázi prověřuje testovací bázi (požadavky, návrhy), a ohodnocuje tak pracovní produkty dříve, než se defekty v nich promítnou do kódu.","b":"Není správně. Ověření souladu s předpisy je samostatný cíl, který s prověřováním testovací báze přímo nesouvisí.","c":"Není správně. Důvěra v kvalitu testovaného objektu vzniká až na základě výsledků jeho testování.","d":"Není správně. Informace pro rozhodnutí poskytují hlavně výsledky testů a reporty, ne prověřování testovací báze."},"obecne":"Sylabus 1.1.1 uvádí mezi typickými cíli testování ohodnocení pracovních produktů jako jsou požadavky, uživatelské scénáře, návrhy a kód. Časný návrh testů odhaluje nejasnosti a defekty v testovací bázi, a přispívá tak k ohodnocení těchto pracovních produktů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"}},{"id":"UC-1-23","n":2,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":1,"q":"Které z následujících tvrzení o týmovém přístupu je PRAVDIVÉ?","m":["<p>Týmový přístup je nejužitečnější při použití u bezpečnostně kritických systémů.<\/p>","<p>Při týmovém přístupu vývojáři a testeři úzce spolupracují, aby se dohodli na strategii testování a rozhodli o přístupech k automatizaci testů.<\/p>","<p>Při týmovém přístupu je sice každý zodpovědný za kvalitu, ale každý člen týmu vykonává pouze úkoly související s jeho rolí.<\/p>","<p>Týmový přístup je obecně lepší než nezávislé testování.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Týmový přístup není určen specificky pro bezpečnostně kritické systémy; u nich naopak může být nutná vysoká úroveň nezávislosti testování.","b":"Je správně. Testeři při týmovém přístupu úzce spolupracují s vývojáři, např. na dohodě o strategii testování a přístupech k automatizaci testů.","c":"Není správně. Každý člen týmu s potřebnými znalostmi a dovednostmi může vykonávat jakýkoliv úkol, nejen úkoly své role.","d":"Není správně. Týmový přístup není obecně lepší než nezávislé testování; vhodnost obou závisí na kontextu projektu."},"obecne":"Sylabus 1.5.2: Při týmovém přístupu testeři úzce spolupracují s vývojáři (např. na dohodě o strategii testování a přístupech k automatizaci testů) i se zástupci byznysu. Každý člen týmu může vykonávat jakýkoliv úkol, pro který má dovednosti, a u bezpečnostně kritických systémů nemusí být týmový přístup vhodný.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"TR-009","n":3,"lo":"FL-1.2.3","k":"K2","k3":true,"vyber":1,"q":"Co je kořenová příčina?","m":["Vždy technická závada v kódu, kterou odhalí ladění","Viditelný projev defektu při provozu systému","Primární důvod vzniku problému, např. situace vedoucí k chybě","Jiné označení pro defekt v kódu nebo v dokumentaci"],"ok":[2],"vys":{"a":"Není správně. Kořenová příčina nemusí být technická, může jít např. o časový tlak nebo nedostatečné školení.","b":"Není správně. Viditelný projev defektu při spuštění je selhání.","c":"Je správně. Sylabus definuje kořenovou příčinu jako primární důvod vzniku problému, např. situaci, která vede k chybě.","d":"Není správně. Defekt je důsledkem chyby, kořenová příčina je důvod, proč k chybě vůbec došlo."},"obecne":"Sylabus 1.2.3: Kořenová příčina je primárním důvodem vzniku problému (např. situace, která vede k chybě). Identifikuje se analýzou kořenových příčin, obvykle po výskytu selhání nebo identifikaci defektu, aby bylo možné zabránit podobným selháním nebo defektům.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.2.3","nazev":"Chyby, defekty, selhání a kořenové příčiny","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-tri-chyby-defekty-selhani-a-korenove-priciny"}},{"id":"UC-1-01","n":4,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Proč je důležité při testování zohledňovat princip Testy se opotřebovávají?","m":["<p>Dynamické testy se opotřebovávají rychleji než statické testy.<\/p>","<p>Testy by neměly být závislé na kontextu.<\/p>","<p>Opakované spouštění stejných testů zvyšuje pravděpodobnost nalezení defektů.<\/p>","<p>Spouštění stále stejných testů dokola snižuje šanci na nalezení nových defektů.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Princip nerozlišuje mezi dynamickými a statickými testy.","b":"Není správně. Testování závislé na kontextu být má; s principem Testy se opotřebovávají to nesouvisí.","c":"Není správně. Opakované spouštění stejných testů pravděpodobnost nalezení nových defektů naopak snižuje.","d":"Je správně. Pokud se stejné testy opakují stále dokola, stávají se méně účinnými a nové defekty neodhalují."},"obecne":"Sylabus 1.3, princip 5: Pokud se stejné testy opakují neustále dokola, stávají se stále méně účinnými a nedochází k odhalování nových defektů. Je proto nutné měnit stávající testy a testovací data, případně vytvořit testy nové; výjimkou je např. automatizované regresní testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UP-4-05","n":5,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"Co je testovací báze?","m":["Soubor znalostí používaný jako základ pro testovací analýzu a návrh testů","Okamžik během vývoje softwaru, kdy by mělo začít testování","Metoda používaná k systematickému odvozování testovacích podmínek","Zdroj pro určení skutečných výsledků sady testů"],"ok":[0],"vys":{"a":"Je správně. Slovník ISTQB definuje testovací bázi jako soubor znalostí použitý jako základ pro testovací analýzu a návrh testů.","b":"Není správně. Okamžik zahájení testování není testovací báze.","c":"Není správně. Metodou pro odvozování testovacích podmínek je technika testování, ne testovací báze.","d":"Není správně. Skutečné výsledky vznikají provedením testů, nelze je určit z testovací báze."},"obecne":"Testovací báze (např. požadavky, uživatelské scénáře, návrh, kód) je soubor znalostí, který se podle sylabu 1.4.1 analyzuje při testovací analýze s cílem identifikovat testovací podmínky a slouží jako základ pro návrh testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"UP-5-05","n":6,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Rozlište následující pracovní produkty testování (1–4) tak, že je přiřadíte ke správnému popisu (A–D).<\/p><p>1. Sada testů<br>2. Testovací případ<br>3. Testovací skript<br>4. Testovací listina<\/p><p>A. Skupina testovacích skriptů, které se mají provést v jednom běhu testů<br>B. Posloupnost instrukcí pro provedení testu<br>C. Obsahuje vstupy, vstupní podmínky a očekávané výsledky<br>D. Popis cílů testování a případných testovacích nápadů, jak testovat<\/p>","m":["1A, 2C, 3B, 4D","1D, 2B, 3A, 4C","1A, 2C, 3D, 4B","1D, 2C, 3B, 4A"],"ok":[0],"vys":{"a":"Je správně. Sada testů = skupina skriptů (A), testovací případ = vstupy a očekávané výsledky (C), testovací skript = posloupnost instrukcí (B), testovací listina = cíle a testovací nápady (D).","b":"Není správně. Testovací listina nepopisuje sadu testů a testovací skript není skupinou skriptů.","c":"Není správně. Testovací skript a testovací listina jsou zaměněny.","d":"Není správně. Sada testů a testovací listina jsou zaměněny."},"obecne":"Sada testů je skupina testovacích skriptů nebo procedur provedených v jednom běhu (výstup implementace testování), testovací případ obsahuje vstupní podmínky, vstupy, očekávané výsledky a výstupní podmínky, testovací skript je posloupnost instrukcí pro provedení testu a testovací listina (sylabus 4.4.2) popisuje cíle testování a testovací nápady pro průzkumné testování v relacích.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"TR-010","n":7,"lo":"FL-1.4.4","k":"K2","k3":true,"vyber":1,"q":"Proč je důležité udržovat trasovatelnost mezi testovací bází a testwarem?","m":["Umožňuje automaticky generovat testovací skripty z požadavků","Je vyžadována jen u bezpečnostně kritických a regulovaných systémů","Umožňuje vyhodnocovat pokrytí, určit dopad změn a usnadňuje audity","Nahrazuje reporty o postupu prací i souhrnné reporty z testování"],"ok":[2],"vys":{"a":"Není správně. Generování skriptů je úkolem nástrojů, ne přínosem trasovatelnosti.","b":"Není správně. Trasovatelnost je užitečná v každém projektu, nejen u kritických systémů.","c":"Je správně. Sylabus uvádí vyhodnocení pokrytí, určení dopadu změn a usnadnění auditu jako hlavní přínosy trasovatelnosti.","d":"Není správně. Trasovatelnost reporty nenahrazuje, ale zlepšuje jejich srozumitelnost."},"obecne":"Sylabus 1.4.4: Přesná trasovatelnost umožňuje vyhodnocovat pokrytí, určit dopad změn, usnadňuje provádění auditu, pomáhá plnit kritéria správného řízení IT a zlepšuje srozumitelnost reportů z testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.4","nazev":"Trasovatelnost mezi testovací bází a pracovními produkty z testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-ctyri-trasovatelnost-mezi-testovaci-bazi-a-pracovnimi-produkty-z-testovani"}},{"id":"TR-012","n":8,"lo":"FL-1.5.1","k":"K2","k3":true,"vyber":1,"q":"Která z uvedených dovedností NEPATŘÍ mezi obecné dovednosti, které sylabus uvádí jako důležité pro testery?","m":["Analytické a kritické myšlení","Znalost domény","Komunikační dovednosti a aktivní naslouchání","Programování v jazyce symbolických adres (assembler)"],"ok":[3],"vys":{"a":"Není správně. Analytické a kritické myšlení a kreativita zvyšují efektivitu testování.","b":"Není správně. Znalost domény pomáhá porozumět koncovým uživatelům a komunikovat s nimi.","c":"Není správně. Komunikační dovednosti a aktivní naslouchání jsou pro testery klíčové.","d":"Je správně. Znalost konkrétního programovacího jazyka sylabus mezi obecné dovednosti testera neuvádí."},"obecne":"Sylabus 1.5.1: Mezi obecné dovednosti testera patří znalost testování, důkladnost a pečlivost, komunikační dovednosti a aktivní naslouchání, analytické a kritické myšlení, technické znalosti a znalost domény. Znalost konkrétního programovacího jazyka mezi nimi není.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.1","nazev":"Obecné dovednosti potřebné pro testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-jedna-obecne-dovednosti-potrebne-pro-testovani"}},{"id":"UP-5-10","n":9,"lo":"FL-2.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Jsou dána následující tvrzení o vztazích mezi činnostmi vývoje softwaru a testovacími činnostmi v životním cyklu vývoje softwaru:<\/p><p>1. Každá vývojová činnost by měla mít odpovídající testovací činnost.<\/p><p>2. Revize by měly začít, jakmile jsou k dispozici finální verze dokumentů.<\/p><p>3. Návrh a implementace testů by měly začít během odpovídající vývojové činnosti.<\/p><p>4. Testovací činnosti by měly začít v raných fázích životního cyklu vývoje softwaru.<\/p><p><br><\/p><p>Která z následujících možností SPRÁVNĚ ukazuje, která tvrzení jsou pravdivá a která nepravdivá?<\/p><p><br><\/p>","m":["<p>Pravdivá – 1, 4; nepravdivá – 2, 3<\/p>","<p>Pravdivá – 1, 2; nepravdivá – 3, 4<\/p>","<p>Pravdivá – 2, 3; nepravdivá – 1, 4<\/p>","<p>Pravdivá – 1, 2, 4; nepravdivá – 3<\/p>"],"ok":[0],"vys":{"a":"Je správně. Pravdivá jsou tvrzení 1 a 4; tvrzení 2 a 3 jsou nepravdivá.","b":"Není správně. Tvrzení 2 je nepravdivé (revize mají začít už u pracovních verzí) a tvrzení 4 je pravdivé.","c":"Není správně. Tvrzení 1 je pravdivé a tvrzení 2 a 3 jsou nepravdivá.","d":"Není správně. Tvrzení 2 je nepravdivé – testeři se zapojují do revize už u pracovních verzí, ne až u finálních."},"obecne":"<p>Sylabus 2.1.2:<\/p><p>1. PRAVDA – ke každé vývojové činnosti existuje odpovídající testovací činnost.<\/p><p>2. NEPRAVDA – testeři se zapojují do revize, jakmile jsou k dispozici pracovní verze (drafty), ne až finální verze.<\/p><p>3. NEPRAVDA – během odpovídající vývojové fáze má začít testovací analýza a návrh testů, nikoli implementace testů.<\/p><p>4. PRAVDA – včasné testování a shift left.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"}},{"id":"TR-022","n":10,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"Co mají vývoj řízený testy (TDD), vývoj řízený akceptačními testy (ATDD) a vývoj řízený chováním (BDD) společné?","m":["Testy se v nich vždy zapisují formou modelů v jazyce UML","Testy se definují dříve, než je napsán odpovídající kód","Používají se výhradně v úrovni systémového testování","Díky nim již není potřeba provádět statické testování"],"ok":[1],"vys":{"a":"Není správně. Žádný z těchto přístupů nevyžaduje modely v UML; BDD naopak používá přirozený jazyk.","b":"Je správně. Všechny tři přístupy definují testy před napsáním kódu, a uplatňují tak včasné testování a shift left.","c":"Není správně. TDD se uplatňuje typicky při testování komponent, ATDD a BDD na úrovni akceptačních kritérií.","d":"Není správně. Tyto přístupy statické testování (např. revize) nenahrazují."},"obecne":"Sylabus 2.1.3: TDD, ATDD i BDD jsou aplikací principů včasného testování a shift left – testy jsou definovány dříve, než je napsán kód. Všechny tyto přístupy podporují iterativní model vývoje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UC-2-11","n":11,"lo":"FL-2.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o roli testerů v sekvenčních modelech vývoje je pravdivé?<\/p>","m":["<p>Testeři se obvykle účastní revizí požadavků, testovací analýzy a návrhu testů a dynamické testování mohou provádět během celého SDLC.<\/p>","<p>Testeři se obvykle účastní pouze provedení testů a reportování defektů a do jiných fází SDLC zapojeni nejsou.<\/p>","<p>Testeři se obvykle účastní revizí požadavků, testovací analýzy a návrhu testů, ale dynamické testování mohou provádět až v pozdějších fázích SDLC.<\/p>","<p>Testeři se obvykle neúčastní žádné fáze sekvenčních SDLC.<\/p>"],"ok":[2],"vys":{"a":"Není správně. V sekvenčních modelech vzniká spustitelný kód až později, dynamické testování proto v raných fázích provádět nelze.","b":"Není správně. Testeři se v sekvenčních modelech zapojují už v počátečních fázích.","c":"Je správně. Testeři se účastní revizí požadavků, testovací analýzy a návrhu testů, dynamické testování je ale možné až později.","d":"Není správně. Testeři se v sekvenčních modelech účastní řady fází SDLC."},"obecne":"Sylabus 2.1.1: v sekvenčních modelech vývoje se testeři v počátečních fázích obvykle účastní revizí požadavků, testovací analýzy a návrhu testů. Spustitelný kód obvykle vzniká až v pozdějších fázích, proto v počátečních fázích nelze provádět dynamické testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.1","nazev":"Vliv životního cyklu vývoje softwaru na testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-jedna-vliv-zivotniho-cyklu-vyvoje-softwaru-na-testovani"}},{"id":"UP-4-11","n":12,"lo":"FL-2.1.5","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností NENÍ příkladem uplatnění přístupu shift left?<\/p>","m":["<p>Revize návrhových dokumentů z hlediska testovatelnosti před zahájením kódování<\/p>","<p>Spouštění statické analýzy kódu ještě před dynamickým testováním<\/p>","<p>Psaní automatizovaných akceptačních testů ještě před zahájením vývoje<\/p>","<p>Provádění testování výkonnosti až během systémového integračního testování<\/p>"],"ok":[3],"vys":{"a":"Není správně. Revize dokumentů před kódováním je příkladem včasného testování, tedy shift left.","b":"Není správně. Spouštění statické analýzy před dynamickým testováním sylabus výslovně uvádí jako příklad shift left.","c":"Není správně. Psaní testů před kódem je typickým příkladem shift left.","d":"Je správně. Testování výkonnosti v pozdní úrovni systémové integrace testování dříve neposouvá; shift left by znamenal např. nefunkcionální testy už při testování komponent."},"obecne":"Sylabus 2.1.5: příklady shift left jsou revize specifikací z pohledu testerů, psaní testovacích případů před kódem, používání CI/CD, spouštění statické analýzy před dynamickým testováním a provádění nefunkcionálních testů už v úrovni testování komponent.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"}},{"id":"UP-5-13","n":13,"lo":"FL-2.2.1","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení porovnávajících testování komponent a systémové testování je PRAVDIVÉ?<\/p>","m":["<p>Testovací případy pro testování komponent se obvykle odvozují ze specifikací komponent, detailního návrhu nebo datových modelů, zatímco pro systémové testování ze specifikací požadavků na systém.<\/p>","<p>Za testování komponent odpovídají testeři, zatímco za systémové testování obvykle odpovídají uživatelé systému.<\/p>","<p>Testování komponent se zaměřuje pouze na funkcionální charakteristiky, zatímco systémové testování na funkcionální i nefunkcionální charakteristiky.<\/p>","<p>Testování komponent ověřuje funkcionalitu samostatně testovatelných modulů, objektů a tříd, zatímco systémové testování ověřuje rozhraní mezi komponentami a interakce mezi různými částmi systému.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Testovací báze se mezi úrovněmi liší: u komponent jde o specifikace komponent a detailní návrh, u systémového testování o specifikace systému.","b":"Není správně. Testování komponent obvykle provádějí vývojáři a systémové testování často nezávislý testovací tým.","c":"Není správně. Nefunkcionální testy lze provádět i při testování komponent.","d":"Není správně. Rozhraní a interakce mezi komponentami jsou předmětem integračního testování komponent, ne systémového testování."},"obecne":"Sylabus 2.2.1: úrovně testování se liší mj. testovaným objektem, cíli, testovací bází a zodpovědnostmi. Testování komponent se zaměřuje na izolované komponenty a obvykle jej provádějí vývojáři; systémové testování se zaměřuje na chování celého systému, vychází ze specifikací systému a může jej provádět nezávislý testovací tým.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"}},{"id":"TR-082","n":14,"lo":"FL-2.2.3","k":"K2","k3":true,"vyber":1,"q":"Po opravě defektu, kvůli kterému selhal testovací případ TC1, provede tester druhý testovací cyklus: znovu spustí TC1 a navíc TC5, který v prvním cyklu prošel a s opravou přímo nesouvisí. Jak se nazývá opětovné spuštění TC5?","m":["Konfirmační test","Regresní test","Test komponenty","Akceptační test"],"ok":[1],"vys":{"a":"Není správně. Konfirmačním testem je opětovné spuštění TC1, který ověřuje samotnou opravu.","b":"Je správně. TC5 dříve prošel a ověřuje, zda oprava nezpůsobila nežádoucí dopad jinde – jde o regresní test.","c":"Není správně. Test komponenty označuje úroveň testování, ne účel opakovaného spuštění testu.","d":"Není správně. Akceptační test je zařazen podle úrovně testování, ne podle důvodu opakovaného spuštění."},"obecne":"Sylabus 2.2.3: konfirmační testování ověřuje, že byl původní defekt opraven (zde opětovné spuštění TC1). Regresní testování ověřuje, zda změna nezpůsobila nežádoucí dopady v jiných částech (zde opětovné spuštění TC5, který dříve prošel).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.3","nazev":"Konfirmační a regresní testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-tri-konfirmacni-a-regresni-testovani"}},{"id":"UP-3-15","n":15,"lo":"FL-3.1.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností obsahuje pouze vhodné kandidáty pro manuální statické testování (revizi)?<\/p>","m":["<p>Specifikace požadavků, plán testování, kód, úniky paměti.<\/p>","<p>Specifikace požadavků, kód, čtení založené na perspektivách.<\/p>","<p>Specifikace požadavků, testovací případy, uživatelské příručky.<\/p>","<p>Specifikace požadavků, uživatelské příručky, testování výkonnosti.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Úniky paměti nejsou pracovní produkt, ale typ defektu.","b":"Není správně. Čtení založené na perspektivách je technika revize, nikoli pracovní produkt.","c":"Je správně. Specifikace požadavků, testovací případy i uživatelské příručky jsou čitelné pracovní produkty vhodné pro revizi.","d":"Není správně. Testování výkonnosti je činnost, nikoli pracovní produkt k revizi."},"obecne":"Sylabus 3.1.1: revizi lze použít na jakýkoli pracovní produkt, který lze přečíst a porozumět mu, např. specifikace požadavků, testovací případy nebo dokumentaci.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.1","nazev":"Pracovní produkty, které mohou být prověřeny statickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-jedna-pracovni-produkty-ktere-mohou-byt-provereny-statickym-testovanim"}},{"id":"UP-4-17","n":16,"lo":"FL-3.2.3","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností SPRÁVNĚ přiřazuje role a odpovědnosti při formální revizi?<\/p>","m":["<p>Zapisovatel – opravuje defekty v revidovaném pracovním produktu<\/p>","<p>Moderátor – rozhoduje o zdrojích vyčleněných na revizi<\/p>","<p>Vedoucí revize – zajišťuje efektivní průběh revizních schůzek<\/p>","<p>Manažer – rozhoduje o tom, co se bude revidovat<\/p>"],"ok":[3],"vys":{"a":"Není správně. Revidovaný pracovní produkt opravuje autor.","b":"Není správně. O zdrojích pro revizi rozhoduje manažer.","c":"Není správně. Efektivní průběh revizních schůzek zajišťuje moderátor.","d":"Je správně. Manažer rozhoduje o tom, co má být revidováno, a o zdrojích."},"obecne":"Sylabus 3.2.3: manažer rozhoduje o tom, co má být revidováno a jaké zdroje budou využity; moderátor zajišťuje efektivní průběh revizních schůzek; autor opravuje pracovní produkt; zapisovatel zaznamenává informace z revize.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"}},{"id":"TR-033","n":17,"lo":"FL-3.1.3","k":"K2","k3":true,"vyber":1,"q":"Které z následujících tvrzení NEJLÉPE vystihuje rozdíl mezi statickým a dynamickým testováním?","m":["Statické testování nachází defekty přímo, dynamické hledá selhání, z nichž se defekty určí analýzou","Statické testování hledá selhání za běhu, dynamické odhaluje defekty přímo v kódu","Statické testování lze použít pouze na zdrojový kód, dynamické na jakýkoli pracovní produkt","Dynamické testování je vždy levnější, protože nevyžaduje účast zainteresovaných stran"],"ok":[0],"vys":{"a":"Je správně. Statické testování nachází defekty přímo, dynamické testování způsobuje selhání, z nichž se defekty určí následnou analýzou.","b":"Není správně. Role jsou prohozené – selhání hledá dynamické testování.","c":"Není správně. Je to naopak: statické testování lze použít i na nespustitelné pracovní produkty, dynamické jen na spustitelné.","d":"Není správně. Defekty nalezené staticky v rané fázi bývají levnější na opravu; dynamické testování není vždy levnější."},"obecne":"Sylabus 3.1.3: statické testování najde defekty přímo, zatímco dynamické testování hledá selhání, ze kterých jsou příslušné defekty určeny následnou analýzou. Statické testování lze navíc použít i na nespustitelné pracovní produkty.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"}},{"id":"TR-036","n":18,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"Co je hlavním cílem inspekce jako typu revize?","m":["Vzdělávat revidující bez nutnosti přípravy","Nalézt maximální počet anomálií","Dosáhnout shody v technickém problému","Generovat nové nápady bez zaznamenání výsledků"],"ok":[1],"vys":{"a":"Není správně. Vzdělávání revidujících je jedním z cílů předvedení, nikoli hlavním cílem inspekce.","b":"Je správně. Hlavním cílem inspekce je nacházet maximální počet anomálií.","c":"Není správně. Dosažení shody a rozhodnutí o technickém problému je hlavním cílem technické revize.","d":"Není správně. Inspekce má formální dokumentovaný výstup a shromažďují se při ní metriky."},"obecne":"Sylabus 3.2.4: inspekce je nejformálnějším typem revize; jejím hlavním cílem je nacházet maximální počet anomálií. Shromažďují se při ní metriky pro zlepšování SDLC včetně procesu inspekce.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UC-4-52","n":19,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících technik testování je založená na struktuře?<\/p>","m":["<p>Analýza hraničních hodnot<\/p>","<p>Testování přechodů stavů<\/p>","<p>Testování větví<\/p>","<p>Rozdělení tříd ekvivalence<\/p>"],"ok":[2],"vys":{"a":"Není správně. Analýza hraničních hodnot je technika testování černé skříňky.","b":"Není správně. Testování přechodů stavů je technika testování černé skříňky.","c":"Je správně. Testování větví je technika testování bílé skříňky, tedy technika založená na struktuře.","d":"Není správně. Rozdělení tříd ekvivalence je technika testování černé skříňky."},"obecne":"Sylabus 4.1: techniky testování bílé skříňky (známé také jako techniky založené na struktuře) vycházejí z analýzy vnitřní struktury testovaného objektu. Sylabus z nich popisuje testování příkazů a testování větví.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"TR-056","n":20,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"Testovaná položka má dva nezávislé vstupní parametry; pro každý z nich byly identifikovány 2 třídy ekvivalence. Jaký je MINIMÁLNÍ počet testovacích případů pro dosažení 100% pokrytí každé volby (Each Choice)?","m":["1","2","4","8"],"ok":[1],"vys":{"a":"Není správně. Jeden test pokryje z každého parametru jen jednu třídu, druhá třída každého parametru zůstane nepokryta.","b":"Je správně. Každý test může pokrýt jednu třídu z každého parametru, takže dva testy pokryjí všechny čtyři třídy.","c":"Není správně. Čtyři testy by byly potřeba pro všechny kombinace tříd, ty ale pokrytí každé volby nevyžaduje.","d":"Není správně. Tolik testů není potřeba ani pro všechny kombinace (2 × 2 = 4)."},"obecne":"Sylabus 4.2.1: Pokrytí každé volby vyžaduje, aby testovací případy pokryly každou třídu z každé množiny tříd alespoň jednou, a nebere v úvahu kombinace tříd. Minimum je tedy rovno největšímu počtu tříd jednoho parametru, zde 2.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-51","n":21,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Je dána následující specifikace (věk je celé číslo):<\/p><ul><li>Pokud je vám méně než 18 let, jste příliš mladí na to, abyste si mohli pronajmout byt.<\/li><li>Pokud je váš věk mezi 18 a 30 lety včetně, získáte slevu 20 %.<\/li><li>Kdokoli starší 30 let nemá na slevu nárok.<\/li><\/ul><p>Vámi navržené testovací případy dosáhly 100% pokrytí dvouhodnotovou analýzou hraničních hodnot. Kvůli známým rizikům potřebujete dosáhnout také 100% pokrytí tříhodnotovou analýzou hraničních hodnot. Které hodnoty je nutné do sady testů doplnit?<\/p>","m":["<p>16, 19, 29, 32<\/p>","<p>16, 32<\/p>","<p>19, 29<\/p>","<p>V tomto příkladu není mezi dvouhodnotovou a tříhodnotovou BVA žádný rozdíl<\/p>"],"ok":[0],"vys":{"a":"Je správně. Dvouhodnotová BVA použila 17, 18, 30, 31; tříhodnotová vyžaduje 16, 17, 18, 19, 29, 30, 31, 32, takže chybí 16, 19, 29 a 32.","b":"Není správně. Chybí také sousedé 19 a 29.","c":"Není správně. Chybí také sousedé 16 a 32.","d":"Není správně. Tříhodnotová BVA přidává ke každé hraniční hodnotě oba sousedy, takže vyžaduje další hodnoty."},"obecne":"Sylabus 4.2.2: hraniční hodnoty jsou 17, 18, 30 a 31 (dvouhodnotová BVA). Tříhodnotová BVA přidává ke každé hraniční hodnotě oba sousedy: 16, 17, 18, 19, 29, 30, 31, 32. Doplnit je tedy třeba 16, 19, 29 a 32.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UP-1-22","n":22,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Je dána následující rozhodovací tabulka:<\/p><table><tr><th>Podmínky / akce<\/th><th>R1<\/th><th>R2<\/th><th>R3<\/th><th>R4<\/th><\/tr><tr><td>Platné uživatelské jméno<\/td><td>F<\/td><td>T<\/td><td>T<\/td><td>T<\/td><\/tr><tr><td>Platné heslo<\/td><td>–<\/td><td>F<\/td><td>T<\/td><td>T<\/td><\/tr><tr><td>Dostatečný zůstatek<\/td><td>–<\/td><td>–<\/td><td>F<\/td><td>T<\/td><\/tr><tr><td>Hlášení „Neplatné přihlašovací údaje“<\/td><td>X<\/td><td>X<\/td><td><\/td><td><\/td><\/tr><tr><td>Hlášení „Nedostatečný zůstatek“<\/td><td><\/td><td><\/td><td>X<\/td><td><\/td><\/tr><tr><td>Provedení platby<\/td><td><\/td><td><\/td><td><\/td><td>X<\/td><\/tr><\/table><p>Již existují 2 testovací případy:<\/p><p>1 – neplatné uživatelské jméno<br>2 – platné uživatelské jméno, platné heslo a dostatečný zůstatek<\/p><p>Které testovací případy je třeba doplnit, aby bylo s co NEJMENŠÍM počtem testů dosaženo 100% pokrytí rozhodovací tabulky?<\/p>","m":["<p>Jeden testovací případ: platné uživatelské jméno a heslo<\/p>","<p>Dva testovací případy: 1- platné uživatelské jméno a neplatné heslo 2- platné uživatelské jméno a platné heslo, ale nedostatečný zůstatek<\/p>","<p>Tři testovací případy: 1- neplatné uživatelské jméno a platné heslo 2- platné uživatelské jméno a neplatné heslo 3- platné uživatelské jméno a platné heslo, ale nedostatečný zůstatek<\/p>","<p>Dva testovací případy: 1- neplatné uživatelské jméno a platné heslo 2- platné uživatelské jméno a neplatné heslo, ale nedostatečný zůstatek<\/p>"],"ok":[1],"vys":{"a":"Není správně. Platné jméno a heslo vede k pravidlu R3 nebo R4 podle zůstatku; pravidlo R2 by zůstalo nepokryto.","b":"Je správně. První test pokryje R2, druhý R3; spolu s existujícími testy (R1 a R4) jsou pokryta všechna 4 pravidla.","c":"Není správně. Tato sada sice pokryje všechna pravidla, ale první test znovu pokrývá R1, takže nejde o nejmenší počet testů.","d":"Není správně. První test pokrývá opět R1 (heslo je pro neplatné jméno irelevantní) a druhý R2; pravidlo R3 zůstane nepokryto."},"obecne":"<p>Sylabus 4.2.3: Položkami pokrytí jsou proveditelné sloupce tabulky. Existující testy pokrývají R1 a R4, chybí R2 (platné jméno, neplatné heslo) a R3 (platné jméno i heslo, nedostatečný zůstatek). Stačí tedy přesně dva další testy.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UP-6-23","n":23,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Uvažujte následující stavový diagram samoobslužného čerpacího stojanu, který přijímá pouze platební karty:<\/p><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 400\" width=\"100%\" role=\"img\" aria-label=\"Stavový diagram samoobslužného čerpacího stojanu se čtyřmi stavy; přechody jsou vypsány pod diagramem.\" font-family=\"inherit\"><defs><marker id=\"sip-up623\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"currentColor\"/><\/marker><\/defs><rect x=\"40\" y=\"90\" width=\"170\" height=\"44\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"125\" y=\"117\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">ČEKÁNÍ NA ZÁKAZNÍKA<\/text><rect x=\"430\" y=\"90\" width=\"170\" height=\"44\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"515\" y=\"117\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">ČEKÁNÍ NA DRUH PALIVA<\/text><rect x=\"430\" y=\"320\" width=\"170\" height=\"44\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"515\" y=\"347\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">ČEKÁNÍ NA ČERPÁNÍ<\/text><rect x=\"40\" y=\"320\" width=\"170\" height=\"44\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"125\" y=\"347\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">ČERPÁNÍ<\/text><circle cx=\"12\" cy=\"112\" r=\"5\" fill=\"currentColor\"/><path d=\"M17,112 L38,112\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><path d=\"M100,90 C80,40 170,40 150,88\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"125\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">vložení karty [neplatná] / chybové hlášení<\/text><path d=\"M210,102 L428,102\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"320\" y=\"78\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">vložení karty [platná] /<\/text><text x=\"320\" y=\"93\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">výzva k volbě paliva<\/text><path d=\"M430,124 L212,124\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"320\" y=\"142\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">zrušení nebo časový limit /<\/text><text x=\"320\" y=\"157\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">rozloučení<\/text><path d=\"M515,134 L515,318\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"505\" y=\"220\" text-anchor=\"end\" font-size=\"12\" fill=\"currentColor\">stisk tlačítka paliva /<\/text><text x=\"505\" y=\"235\" text-anchor=\"end\" font-size=\"12\" fill=\"currentColor\">zahájení čerpání<\/text><path d=\"M430,330 L182,136\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"345\" y=\"292\" text-anchor=\"end\" font-size=\"12\" fill=\"currentColor\">zrušení nebo časový limit /<\/text><text x=\"345\" y=\"307\" text-anchor=\"end\" font-size=\"12\" fill=\"currentColor\">rozloučení<\/text><path d=\"M430,352 L212,352\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"320\" y=\"376\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">zákazník čerpá /<\/text><text x=\"320\" y=\"391\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">hlášení o zahájení čerpání<\/text><path d=\"M125,320 L125,136\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"135\" y=\"210\" text-anchor=\"start\" font-size=\"12\" fill=\"currentColor\">zákazník skončil /<\/text><text x=\"135\" y=\"225\" text-anchor=\"start\" font-size=\"12\" fill=\"currentColor\">tisk účtenky<\/text><\/svg><p>Přechody (událost [podmínka] / akce):<\/p><ol><li>ČEKÁNÍ NA ZÁKAZNÍKA → ČEKÁNÍ NA ZÁKAZNÍKA: vložení karty [neplatná] / chybové hlášení<\/li><li>ČEKÁNÍ NA ZÁKAZNÍKA → ČEKÁNÍ NA DRUH PALIVA: vložení karty [platná] / výzva k volbě paliva<\/li><li>ČEKÁNÍ NA DRUH PALIVA → ČEKÁNÍ NA ZÁKAZNÍKA: zrušení nebo časový limit / rozloučení<\/li><li>ČEKÁNÍ NA DRUH PALIVA → ČEKÁNÍ NA ČERPÁNÍ: stisk tlačítka paliva / zahájení čerpání<\/li><li>ČEKÁNÍ NA ČERPÁNÍ → ČEKÁNÍ NA ZÁKAZNÍKA: zrušení nebo časový limit / rozloučení<\/li><li>ČEKÁNÍ NA ČERPÁNÍ → ČERPÁNÍ: zákazník čerpá / hlášení o zahájení čerpání<\/li><li>ČERPÁNÍ → ČEKÁNÍ NA ZÁKAZNÍKA: zákazník skončil / tisk účtenky<\/li><\/ol><p>Chcete navrhnout minimální počet testů, které pokryjí každý přechod ve stavovém diagramu. Každý test musí začínat v počátečním stavu ČEKÁNÍ NA ZÁKAZNÍKA a končí, jakmile se systém do tohoto stavu znovu vrátí. Kolik testů potřebujete?<\/p>","m":["<p>1<\/p>","<p>4<\/p>","<p>7<\/p>","<p>Nekonečně mnoho<\/p>"],"ok":[1],"vys":{"a":"Není správně. Každý test končí prvním návratem do stavu ČEKÁNÍ NA ZÁKAZNÍKA, jeden test proto pokryje jen jeden ze čtyř přechodů do tohoto stavu.","b":"Je správně. Do stavu ČEKÁNÍ NA ZÁKAZNÍKA vedou 4 přechody (1, 3, 5, 7) a každý test končí právě jedním z nich; 4 testy zároveň stačí na pokrytí všech 7 přechodů.","c":"Není správně. 7 je počet přechodů; testy, které procházejí přechody 2, 4 a 6, je pokryjí společně, takže 7 testů není minimum.","d":"Není správně. Přechodů je konečný počet a pro jejich pokrytí stačí konečný počet testů."},"obecne":"<p>Sylabus 4.2.4: Pro pokrytí platných přechodů musí testy provést každý přechod alespoň jednou. Protože test končí prvním návratem do počátečního stavu a do něj vedou 4 přechody, jsou potřeba alespoň 4 testy: neplatná karta (1); platná karta a zrušení (2, 3); platná karta, volba paliva a zrušení (2, 4, 5); úplný nákup (2, 4, 6, 7). Tyto 4 testy pokryjí všech 7 přechodů.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UC-4-55","n":24,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Jaký je minimální počet testovacích případů potřebný pro 100% pokrytí příkazů a pro 100% pokrytí větví u následujícího kódu?<\/p><pre>int vyska = nactiVysku();\nint hmotnost = nactiHmotnost();\nString poznamka = \"\";\nif (vyska &gt; 140) {\n    poznamka = poznamka + \"Vysoký pacient. \";\n}\nif (hmotnost &gt; 70) {\n    poznamka = poznamka + \"Vyšší hmotnost. \";\n}\nvypis(poznamka);<\/pre>","m":["<p>4 testovací případy pro pokrytí příkazů, 2 testovací případy pro pokrytí větví<\/p>","<p>2 testovací případy pro pokrytí příkazů, 2 testovací případy pro pokrytí větví<\/p>","<p>1 testovací případ pro pokrytí příkazů, 3 testovací případy pro pokrytí větví<\/p>","<p>1 testovací případ pro pokrytí příkazů, 2 testovací případy pro pokrytí větví<\/p>"],"ok":[3],"vys":{"a":"Není správně. Pro pokrytí příkazů nejsou potřeba 4 testy – obě větve if jsou bez else a provede je jediný test.","b":"Není správně. Pro pokrytí příkazů stačí jeden test, v němž jsou obě podmínky pravdivé (např. výška 150, hmotnost 80).","c":"Není správně. Pro pokrytí větví stačí dva testy: oba výsledky obou rozhodnutí pokryje dvojice „obě podmínky pravdivé“ a „obě nepravdivé“.","d":"Je správně. Test (150, 80) provede všechny příkazy; přidáním testu (120, 50) se pokryjí i nepravdivé výsledky obou rozhodnutí."},"obecne":"Sylabus 4.3.1 a 4.3.2: oba příkazy if jsou bez else, takže jeden test s pravdivými podmínkami provede všechny příkazy. Pro 100% pokrytí větví je nutné pokrýt i nepravdivé výsledky obou rozhodnutí; stačí k tomu jeden další test, v němž jsou obě podmínky nepravdivé.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"TR-098","n":25,"lo":"FL-4.3.3","k":"K2","k3":true,"vyber":1,"q":"Ve kterém z následujících případů pomůže testování bílé skříňky odhalit defekt, který by testování černé skříňky typicky NEODHALILO?","m":["Kód obsahuje navíc funkcionalitu, kterou specifikace vůbec nepožaduje.","Uživatelské rozhraní neodpovídá schválenému grafickému návrhu obrazovek.","Systém nesplňuje dohodnutou maximální dobu odezvy při běžné zátěži.","Systém vůbec neimplementuje jeden z požadavků uvedených ve specifikaci."],"ok":[0],"vys":{"a":"Je správně. Testování bílé skříňky zohledňuje celou implementaci, a tak narazí i na kód, který ve specifikaci není a který by testy odvozené ze specifikace neprověřily.","b":"Není správně. Soulad s grafickým návrhem ověří testování černé skříňky podle návrhu.","c":"Není správně. Dobu odezvy ověřuje testování výkonnosti podle specifikovaných požadavků (černá skříňka).","d":"Není správně. Opomenutý požadavek v kódu není, takže ho testování bílé skříňky neodhalí; to je jeho slabina."},"obecne":"Sylabus 4.3.3: Silnou stránkou technik bílé skříňky je, že zohledňují samotnou implementaci softwaru, což usnadňuje detekci defektů i tehdy, když je specifikace vágní, zastaralá nebo neúplná. Slabinou je, že nemusí odhalit opomenutí implementace požadavků.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.3","nazev":"Význam testování bílé skříňky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-tri-vyznam-testovani-bile-skrinky"}},{"id":"UP-4-26","n":26,"lo":"FL-4.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího by bylo NEJLEPŠÍM základem pro útok na vady?<\/p>","m":["<p>Testovací případy odvozené doménovými experty z byznys procesů<\/p>","<p>Zkušenosti, údaje o defektech a selháních a znalosti o selhávání softwaru<\/p>","<p>Očekávané výsledky získané porovnáním se stávajícím systémem<\/p>","<p>Analýza rizik provedená na začátku projektu<\/p>"],"ok":[1],"vys":{"a":"Není správně. Testy odvozené z byznys procesů vycházejí ze specifikovaného chování (černá skříňka).","b":"Je správně. Seznam možných chyb, defektů a selhání pro útok na vady se sestavuje ze zkušeností, údajů o defektech a selháních a z obecných znalostí o selhávání softwaru.","c":"Není správně. Porovnání se stávajícím systémem je zdroj očekávaných výsledků (testovací orákulum), ne seznam selhání.","d":"Není správně. Analýza rizik slouží k zaměření a prioritizaci testování, ne k sestavení seznamu možných selhání."},"obecne":"<p>Sylabus 4.4.1: Útok na vady je příkladem implementace odhadování chyb. Testeři vytvoří nebo získají seznam možných chyb, defektů a selhání a navrhnou testy, které je odhalí. Seznamy lze sestavit na základě zkušeností, údajů o defektech a selháních nebo obecných znalostí o tom, proč software selhává.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"}},{"id":"UC-4-67","n":27,"lo":"FL-4.4.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností NEJLÉPE vystihuje průzkumné testování?<\/p>","m":["<p>Předvídání nebo odhadování, kde by se mohly vyskytnout defekty<\/p>","<p>Systematický přístup k identifikaci tříd ekvivalence vstupů<\/p>","<p>Souběžný návrh, provádění a vyhodnocování testů spojený s učením se<\/p>","<p>Testování prováděné výhradně podle předem připravených podrobných skriptů<\/p>"],"ok":[2],"vys":{"a":"Není správně. Toto je popis odhadování chyb.","b":"Není správně. Toto je popis rozdělení tříd ekvivalence.","c":"Je správně. Při průzkumném testování jsou testy současně navrhovány, prováděny a vyhodnocovány, zatímco tester získává znalosti o testovaném objektu.","d":"Není správně. Průzkumné testování naopak nepracuje s předem připravenými podrobnými skripty."},"obecne":"<p><strong>Podle sylabu (kap. 4.4.2):<\/strong> Při průzkumném testování jsou testy současně navrhovány, prováděny a vyhodnocovány, zatímco testeři získávají znalosti o testovaném objektu. Testování se (mimo jiné) používá k získání dalších informací o testovaném objektu, k jeho hlubšímu prozkoumání pomocí cílených testů a k vytvoření testů pro dosud neotestované oblasti.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.2","nazev":"Průzkumné testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-dva-pruzkumne-testovani"}},{"id":"UC-4-25","n":28,"lo":"FL-4.5.2","k":"K2","k3":true,"vyber":1,"q":"<p>Mějme následující akceptační kritéria:<\/p><ul><li><p>Uživatel by měl mít k videu přístup z webových stránek, a to buď přes přímý odkaz, nebo procházením knihovny videí na webu.<\/p><\/li><li><p>Video by mělo být přehratelné na řadě zařízení a prohlížečů bez nutnosti instalovat další zásuvné moduly nebo software.<\/p><\/li><li><p>Přehrávač videa by měl mít základní ovládací prvky přehrávání, jako je přehrát, pozastavit a posun.<\/p><\/li><li><p>Přehrávač videa by měl podporovat režim celé obrazovky, aby si uživatel mohl video prohlédnout ve větší velikosti.<\/p><\/li><\/ul><p>Jaký formát byl použit k zápisu těchto kritérií?<\/p>","m":["<p>Orientovaný na data<\/p>","<p>Orientovaný na scénáře<\/p>","<p>Orientovaný na funkce<\/p>","<p>Orientovaný na pravidla<\/p>"],"ok":[3],"vys":{"a":"Není správně. Sylabus formát „orientovaný na data“ nezná.","b":"Není správně. Formát orientovaný na scénáře používá posloupnost Given/When/Then; zde jde o seznam pravidel.","c":"Není správně. Sylabus formát „orientovaný na funkce“ nezná.","d":"Je správně. Kritéria tvoří verifikační seznam s odrážkami, což je typický formát orientovaný na pravidla."},"obecne":"<p>Existuje několik způsobů, jak napsat akceptační kritéria pro uživatelský scénář. Dva nejběžnější formáty jsou:<\/p><ul><li><p>orientovaný na scénáře (např. formát Given/When/Then používaný v BDD)<\/p><\/li><li><p><strong>orientovaný na pravidla (např. verifikační seznam s odrážkami nebo tabulka s mapováním vstupů a výstupů)<\/strong><\/p><\/li><\/ul>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"}},{"id":"UP-1-29","n":29,"lo":"FL-4.5.3","k":"K3","k3":true,"vyber":1,"q":"<p>Pracujete jako tester v agilním projektu a obdržíte následující uživatelský scénář:<\/p><p><em>Jako administrátor chci odebrat existujícímu účtu přístupová oprávnění ke komponentě reportování prodejů v našem e-commerce systému, abychom mohli řídit přístup k údajům o prodejích.<\/em><\/p><p>Testovací případy ATDD zapisujete do tabulky se sloupci ID, Akce, Účet a Očekávaný výsledek. Akce může být jedna z následujících: ‘add-account’, ‘delete-account’, ‘add-privilege’, ‘remove-privilege’, ‘view-sales’ nebo ‘report-sales’.<\/p><p>Všechny tyto akce kromě ‘remove-privilege’ byly úspěšně implementovány a otestovány v předchozích iteracích a testovací účty vytvořené v těchto iteracích (včetně jejich oprávnění) stále existují v testovacích datech.<\/p><p>Která z následujících podmnožin testovacích případů ATDD je proveditelná a zároveň poskytuje NEJRYCHLEJŠÍ zpětnou vazbu k nově přidávané funkci? Každý řádek je zapsán jako (ID, Akce, Účet, Očekávaný výsledek).<\/p>","m":["<p>(1, remove-privilege, test-acct-1, „Oprávnění k prodejním datům odebráno“)<\/p>","<p>(1, add-privilege, test-acct-1, „Oprávnění k prodejním datům přidáno“); (2, remove-privilege, test-acct-1, „Oprávnění k prodejním datům odebráno“)<\/p>","<p>(1, add-account, test-acct-1, „Účet přidán“); (2, add-privilege, test-acct-1, „Oprávnění k prodejním datům přidáno“); (3, remove-privilege, test-acct-1, „Oprávnění k prodejním datům odebráno“)<\/p>","<p>(1, add-account, test-acct-1, „Účet přidán“); (2, add-privilege, test-acct-1, „Oprávnění k prodejním datům přidáno“); (3, report-sales, test-acct-1, „Report prodejů zobrazen“); (4, remove-privilege, test-acct-1, „Oprávnění k prodejním datům odebráno“)<\/p>"],"ok":[0],"vys":{"a":"Je správně. Ostatní akce jsou již otestované a testovací data existují, takže jediný test přímo ověřuje novou funkci a dává nejrychlejší zpětnou vazbu.","b":"Není správně. Přidání oprávnění je již otestováno a jen zbytečně oddaluje zpětnou vazbu k nové funkci.","c":"Není správně. Vytvoření účtu a přidání oprávnění jsou zbytečné kroky, protože testovací účty s oprávněním již existují.","d":"Není správně. Obsahuje ještě více zbytečných kroků (včetně zobrazení reportu), které s novou funkcí přímo nesouvisejí."},"obecne":"<p>Sylabus 4.5.3: Testovací případy ATDD vycházejí z akceptačních kritérií uživatelského scénáře, mají pokrývat jeho charakteristiky a nepřesahovat jeho rámec. Protože ostatní akce i testovací data již existují, stačí jediný test akce ‘remove-privilege’.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"UC-5-22","n":30,"lo":"FL-5.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících činností <strong>NENÍ<\/strong> odpovědností testerů zapojených do plánování iterací?<\/p>","m":["<p>Stanovení testovatelnosti uživatelských scénářů<\/p>","<p>Stanovení přístupu k testování pro celé vydání<\/p>","<p>Podíl na podrobné analýze rizik uživatelských scénářů<\/p>","<p>Rozklad uživatelských scénářů do úkolů, zejména testovacích<\/p>"],"ok":[1],"vys":{},"obecne":"Sylabus 5.1.2: Testeři zapojení do plánování iterací se podílejí na podrobné analýze rizik uživatelských scénářů, stanovují jejich testovatelnost, podílejí se na jejich rozkladu do úkolů (zejména testovacích), odhadují pracnost všech testovacích úkolů a zpřesňují funkcionální a nefunkcionální aspekty testovaného objektu. Stanovení přístupu k testování a plánování testování pro vydání patří k plánování vydání.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.2","nazev":"Přínos testerů při plánování iterací a vydání","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-dva-prinos-testeru-pri-planovani-iteraci-a-vydani"}},{"id":"TR-060","n":31,"lo":"FL-5.1.3","k":"K2","k3":true,"vyber":1,"q":"Jak se nazývají kritéria, která musí být splněna PŘED zahájením určité testovací činnosti?","m":["Akceptační kritéria","Kritéria pokrytí","Vstupní kritéria","Výstupní kritéria"],"ok":[2],"vys":{"a":"Není správně. Akceptační kritéria jsou podmínky, které musí splnit implementace uživatelského scénáře, aby ji zainteresované strany přijaly.","b":"Není správně. Kritéria pokrytí určují, jaké pokrytí má testování dosáhnout; mohou být součástí výstupních kritérií.","c":"Je správně. Vstupní kritéria určují předpoklady pro realizaci dané činnosti.","d":"Není správně. Výstupní kritéria určují podmínky, které musí být splněny, aby bylo možné činnost prohlásit za dokončenou."},"obecne":"Sylabus 5.1.3: Vstupní kritéria určují předpoklady pro realizaci dané činnosti (např. dostupnost zdrojů a testwaru, počáteční úroveň kvality testovaného objektu). Výstupní kritéria určují podmínky, kterých musí být dosaženo, aby bylo možné činnost prohlásit za dokončenou.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"}},{"id":"TR-099","n":32,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"Z historických projektů organizace vyplývá, že pracnost testování činí v průměru 12 % pracnosti vývoje. Pracnost vývoje nového projektu se odhaduje na 500 člověkodnů. Jaký je odhad pracnosti testování při použití odhadu na základě poměrů?","m":["50 člověkodnů","60 člověkodnů","120 člověkodnů","500 člověkodnů"],"ok":[1],"vys":{"a":"Není správně. 50 člověkodnů odpovídá poměru 10 %, nikoli 12 %.","b":"Je správně. 500 × 0,12 = 60 člověkodnů.","c":"Není správně. 120 člověkodnů odpovídá poměru 24 %, nikoli 12 %.","d":"Není správně. 500 člověkodnů je pracnost vývoje, nikoli testování."},"obecne":"Sylabus 5.1.4: Odhad na základě poměrů je technika založená na metrikách – z historických dat organizace se odvodí poměr pracnosti testování k pracnosti vývoje a použije se na nový projekt: 500 × 0,12 = 60 člověkodnů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UP-1-33","n":33,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Jako manažer testování odpovídáte za otestování následujících požadavků:<\/p><ul><li>R1 – Anomálie procesu (vysoká složitost)<\/li><li>R2 – Vzdálené služby (střední složitost)<\/li><li>R3 – Synchronizace (střední složitost)<\/li><li>R4 – Potvrzení (střední složitost)<\/li><li>R5 – Uzavření procesu (nízká složitost)<\/li><li>R6 – Problémy (nízká složitost)<\/li><li>R7 – Finanční data (nízká složitost)<\/li><li>R8 – Data diagramů (nízká složitost)<\/li><li>R9 – Změny uživatelského profilu (střední složitost)<\/li><\/ul><p>Mezi požadavky existují tyto logické závislosti (testy požadavku lze provést až po otestování všech požadavků, na kterých závisí):<\/p><ul><li>R2 závisí na R1.<\/li><li>R4 závisí na R1.<\/li><li>R5 závisí na R4.<\/li><li>R3 závisí na R2 a na R5.<\/li><li>R7 a R8 závisí na R3.<\/li><li>R6 a R9 závisí na R3, R7 a R8 (tj. na dokončení celé skupiny R3, R7, R8).<\/li><\/ul><p>Které z následujících pořadí harmonogramu provedení testů respektuje závislosti mezi požadavky?<\/p>","m":["<p>R1 → R2 → R4 → R5 → R3 → R7 → R8 → R6 → R9<\/p>","<p>R4 → R5 → R1 → R2 → R3 → R7 → R8 → R6 → R9<\/p>","<p>R1 → R2 → R3 → R4 → R5 → R7 → R8 → R6 → R9<\/p>","<p>R1 → R2 → R3 → R7 → R8 → R4 → R5 → R6 → R9<\/p>"],"ok":[0],"vys":{"a":"Je správně. Každý požadavek je zařazen až po všech požadavcích, na kterých závisí.","b":"Není správně. R4 závisí na R1, nemůže se proto testovat jako první.","c":"Není správně. R3 závisí na R5 (a ten na R4), R3 se tedy nesmí testovat před R4 a R5.","d":"Není správně. R3, R7 a R8 jsou zařazeny před R4 a R5, ačkoli R3 na R5 (a nepřímo na R4) závisí."},"obecne":"<p>Sylabus 5.1.5: Při sestavování harmonogramu provedení testů je nutné respektovat závislosti – test, který závisí na jiném, se provede až po něm. Začít lze jen R1 (na ničem nezávisí), následuje R2 a větev R4 → R5; teprve poté R3, pak R7 a R8 a nakonec R6 a R9. Tomu odpovídá pouze pořadí R1, R2, R4, R5, R3, R7, R8, R6, R9.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UP-4-33","n":34,"lo":"FL-5.1.7","k":"K2","k3":true,"vyber":1,"q":"<p>Čím se v modelu testovacích kvadrantů vyznačuje kvadrant Q4?<\/p>","m":["<p>Obsahuje testy zaměřené na technologii, které podporují tým (např. testy komponent).<\/p>","<p>Obsahuje testy zaměřené na technologii, které kritizují produkt (např. testy výkonnosti).<\/p>","<p>Obsahuje převážně manuální testy prováděné koncovými uživateli (např. beta testy).<\/p>","<p>Obsahuje testy zaměřené na byznys, které kritizují produkt (např. testy použitelnosti).<\/p>"],"ok":[1],"vys":{"a":"Není správně. Testy zaměřené na technologii, které podporují tým (testy komponent a integrační testy komponent), patří do kvadrantu Q1.","b":"Je správně. Kvadrant Q4 obsahuje testy zaměřené na technologii, které kritizují produkt – smoke testy a nefunkcionální testy (kromě testů použitelnosti), např. testy výkonnosti.","c":"Není správně. Kvadrant Q4 není vymezen manuálním testováním; jeho testy jsou naopak často automatizované.","d":"Není správně. Testy zaměřené na byznys, které kritizují produkt (průzkumné testování, testování použitelnosti, uživatelské akceptační testování), patří do kvadrantu Q3."},"obecne":"Sylabus 5.1.7: Kvadranty vznikají kombinací dvou hledisek – zaměření na byznys / na technologii a podpora týmu / kritika produktu. Kvadrant Q4 (zaměřený na technologii, kritika produktu) obsahuje smoke testy a nefunkcionální testy kromě testů použitelnosti; tyto testy bývají často automatizované.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"}},{"id":"TR-061","n":35,"lo":"FL-5.2.2","k":"K2","k3":true,"vyber":1,"q":"Jaký je rozdíl mezi projektovým a produktovým rizikem?","m":["Produktová rizika se řeší pouze na úrovni akceptačního testování","Projektová rizika se týkají výhradně práce testovacího týmu","Projektové riziko ohrožuje cíle projektu, produktové kvalitu produktu","Projektové a produktové riziko jsou synonyma pro tutéž kategorii rizik"],"ok":[2],"vys":{"a":"Není správně. Produktová rizika ovlivňují testování na všech úrovních (rozsah, techniky, pokrytí, priority).","b":"Není správně. Projektová rizika se týkají managementu a řízení celého projektu (organizace, lidé, technika, dodavatelé).","c":"Je správně. Projektová rizika ovlivňují harmonogram, rozpočet nebo rozsah projektu, produktová rizika souvisejí s kvalitativními charakteristikami produktu.","d":"Není správně. Sylabus rozlišuje dva typy rizik s různým předmětem – projektová a produktová."},"obecne":"Sylabus 5.2.2: Projektová rizika se týkají managementu a řízení projektu a mohou mít dopad na harmonogram, rozpočet nebo rozsah. Produktová rizika souvisejí s kvalitativními charakteristikami produktu (např. chybějící funkcionalita, nedostatečná doba odezvy, bezpečnostní zranitelnosti).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.2.2","nazev":"Projektová a produktová rizika","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-dva-projektova-a-produktova-rizika"}},{"id":"UP-3-30","n":36,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Chystáte se předat report o postupu prací při testování vyššímu manažerovi, který není specialistou na testování. Které z následujících témat by v tomto reportu NEMĚLO být uvedeno?<\/p>","m":["Stav plnění stanovených výstupních kritérií v porovnání s plánem","Produktová rizika, která již byla zmírněna, a rizika, která zůstávají otevřená","Doporučení k řídicím opatřením, která je vhodné v projektu přijmout","Podrobný technický popis přístupu k testování založeného na rizicích"],"ok":[3],"vys":{"a":"Není správně. Postup vůči plánu a stav kritérií jsou základním obsahem reportu o postupu prací.","b":"Není správně. Nová a změněná rizika patří do reportu o postupu prací a pro manažera jsou podstatná.","c":"Není správně. Report má poskytnout dostatek informací pro případné změny harmonogramu, zdrojů nebo plánu.","d":"Je správně. Podrobný technický popis přístupu k testování patří do plánu testování; manažer bez znalostí testování ho nepotřebuje."},"obecne":"Sylabus 5.3.2: Různé cílové skupiny potřebují v reportech různé informace. Report o postupu prací obsahuje postup vůči plánu, překážky, metriky, nová a změněná rizika a plánované testování; podrobný technický popis přístupu k testování do něj pro vyššího manažera nepatří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"UP-4-37","n":37,"lo":"FL-5.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících tvrzení popisují účel konfiguračního managementu při testování?<\/p><ol><li>Vybrat a zavést vhodný nástroj pro konfigurační management.<\/li><li>Jednoznačně identifikovat položky testwaru a s nimi související vyvinutý software.<\/li><li>Zajistit trasovatelnost mezi položkami testwaru a vyvinutým softwarem.<\/li><li>Umožnit uživatelům konfigurovat software.<\/li><li>Řídit verze softwaru uvolňované do testovacího prostředí.<\/li><\/ol>","m":["<p>2, 3 a 5<\/p>","<p>2, 3 a 4<\/p>","<p>1, 2 a 4<\/p>","<p>1, 3 a 5<\/p>"],"ok":[0],"vys":{"a":"Je správně. Jednoznačná identifikace (2), trasovatelnost (3) a řízení verzí (5) jsou přesně to, co konfigurační management při testování zajišťuje.","b":"Není správně. Konfigurace softwaru uživateli (4) s konfiguračním managementem nesouvisí.","c":"Není správně. Tvrzení 1 a 4 účel konfiguračního managementu nepopisují.","d":"Není správně. Výběr nástroje (1) není účelem konfiguračního managementu, je jen prostředkem k jeho zavedení."},"obecne":"Sylabus 5.4: Konfigurační management zajišťuje, že všechny konfigurační položky, včetně položek testování, jsou jednoznačně identifikovány, mají řízené verze, jsou sledovány jejich změny a jsou provázány s ostatními položkami, aby byla zachována trasovatelnost. Tomu odpovídají tvrzení 2, 3 a 5.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"}},{"id":"UP-3-32","n":38,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Čtyři testeři podali každý report o defektu, v němž popsali problém s přihlášením uživatele. Přihlášení uživatele je kritickou komponentou systému. Následující tabulka shrnuje čtyři podané reporty o defektu:<\/p><table><thead><tr><th>Tester<\/th><th>Popis incidentu<\/th><th>Vstupy / očekávaný a skutečný výsledek<\/th><th>Byznysová priorita (1 vysoká, 2 střední, 3 nízká)<\/th><\/tr><\/thead><tbody><tr><td>Tester 1<\/td><td>Chyba ověření při přihlášení uživatele<\/td><td>Zadal jsem uživatele J SMITH a heslo ABC01, ale dostal jsem chybové hlášení.<\/td><td>1<\/td><\/tr><tr><td>Tester 2<\/td><td>Přihlášení nesplňuje požadavek<\/td><td>Vstupy: zadáno platné uživatelské jméno a heslo.<br>Očekávaný výsledek: zobrazí se hlavní nabídka.<br>Skutečný výsledek: chyba „nesprávné heslo“.<\/td><td>2<\/td><\/tr><tr><td>Tester 3<\/td><td>Chyba ověření hesla při přihlášení<\/td><td>Vstupy: uživatel = J SMITH, heslo = ABC01.<br>Očekávaný výsledek: hlavní nabídka.<br>Skutečný výsledek: chybové hlášení EM008 „Neplatné heslo“.<br>Tento test už mnohokrát prošel.<\/td><td>2<\/td><\/tr><tr><td>Tester 4<\/td><td>Chyba ověření hesla<\/td><td>Vstupy: uživatel = J SMITH, heslo = ABC01.<br>Očekávaný výsledek: hlavní nabídka.<br>Skutečný výsledek: EM008 „Neplatné heslo“.<br>Pozn.: stejné vstupy fungovaly včera, před dodáním vydání 1.2.<\/td><td>1<\/td><\/tr><\/tbody><\/table><p>Který tester reportoval defekt NEJÚČINNĚJI s ohledem na uvedené informace a prioritu?<\/p>","m":["<p>Tester 1<\/p>","<p>Tester 2<\/p>","<p>Tester 3<\/p>","<p>Tester 4<\/p>"],"ok":[3],"vys":{"a":"Není správně. Priorita je správná, ale report je nestrukturovaný – chybí očekávaný výsledek i přesné chybové hlášení.","b":"Není správně. Report neuvádí konkrétní vstupní data, takže defekt nelze spolehlivě reprodukovat, a priorita 2 je u kritické komponenty příliš nízká.","c":"Není správně. Report je dobře strukturovaný a reprodukovatelný, ale priorita 2 neodpovídá kritické komponentě.","d":"Je správně. Report obsahuje konkrétní vstupy, očekávaný i skutečný výsledek, správnou prioritu 1 a navíc kontext – defekt se projevil po dodání vydání 1.2."},"obecne":"<p>Sylabus 5.5: Report o defektu má obsahovat mimo jiné kroky a data pro reprodukci, očekávaný a skutečný výsledek, závažnost či prioritu a kontext (např. testovaný objekt a jeho verzi). Všechny tyto údaje včetně správné priority pro kritickou komponentu a informace o vydání 1.2 obsahuje jen report testera 4.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UP-3-33","n":39,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Typický nástroj pro provádění testů by měl umět všechny následující činnosti KROMĚ:<\/p>","m":["<p>opakovaného přehrávání vstupů podle naprogramovaného skriptu<\/p>","<p>nahrávání testovacích vstupů<\/p>","<p>generování očekávaných výsledků<\/p>","<p>porovnání očekávaných výsledků se skutečnými výsledky<\/p>"],"ok":[2],"vys":{"a":"Není správně. Přehrávání vstupů podle skriptu je typickou funkcí nástroje pro provádění testů.","b":"Není správně. Nahrávání testovacích vstupů je typickou funkcí nástroje pro provádění testů.","c":"Je správně. Očekávané výsledky se určují při návrhu testů (z testovací báze nebo testovacího orákula), nástroj pro provádění testů je negeneruje.","d":"Není správně. Porovnání očekávaných a skutečných výsledků je typickou funkcí nástroje pro provádění testů."},"obecne":"Sylabus 6.1: nástroje pro provádění testů a měření pokrytí usnadňují automatizované provádění testů – přehrávají vstupy, porovnávají očekávané výsledky se skutečnými a zaznamenávají výsledky. Očekávané výsledky však musí být určeny při návrhu testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-2-40","n":40,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která položka správně uvádí možné riziko automatizace testů?<\/p>","m":["<p>Nástroj se nepoužívá v každém projektu.<\/p>","<p>Realistické odhady času, nákladů a pracnosti zavedení nástroje.<\/p>","<p>Objektivnější hodnocení (např. měření pokrytí).<\/p>","<p>Dodavatel nástroje může ukončit činnost.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Nepoužívání nástroje v každém projektu není rizikem automatizace.","b":"Není správně. Rizikem jsou nepřesné odhady; realistické odhady riziko naopak snižují.","c":"Není správně. Objektivnější hodnocení je přínosem automatizace.","d":"Je správně. Ukončení činnosti dodavatele, vyřazení nebo prodej nástroje je jedním z rizik automatizace."},"obecne":"Sylabus 6.2 uvádí mezi riziky automatizace testů to, že dodavatel nástroje může ukončit činnost, nástroj vyřadit z provozu nebo jej prodat jinému dodavateli.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}}]};
